// The following code tests harbour's ability to cope with parenthesized
// expressions.

// These tests were written by Dave Pearson <davep@hagbard.demon.co.uk> and
// are placed into the public domain.

// This file is OK to have warnings.
#ifdef __HARBOUR__
   #pragma -es0
#endif

PROCEDURE Main()

   LOCAL x
   LOCAL y

   // Simple one to start with.
   x := ( 1 )
   ? x

   // Now with a little more complex:
   x := ( 1, 2 )
   ? x

   // And a little more, this is really the same as the previous one.
   x := ( 1, 2, 3 )
   ? x

   // Expression within expression
   x := ( ( 1, 2, 3 ) )
   ? x

   // And a little more:
   x := ( ( 1, 2, 3 ), ( 1, 2, 3 ) )
   ? x

   // Some inline assignments
   x := ( y := 10, y )
   ? x

   x := ( ( y := ( 1, 2, 3 ) ), y * ( 10, 20, 30 ) )
   ? x

   // Now mix with statements and functions
   ? ( 1, 2, 3 )

   IF ( y := .T. )
      ? "Working"
   ELSE
      ? "Borken"
   ENDIF

   IF ( x := 10, y := ( x == 10 ) )
      ? "Working"
   ELSE
      ? "Broken"
   ENDIF

   IF ( Something( 1, 2, 3 ), .T. )
      ? "Working"
   ELSE
      ? "Broken"
   ENDIF

   ?

   // Now even some more testing of related code
   // placed into public domain by Ryszard Glab

   ? IF( (.F.,0,.T.), ("some", "text", "IF Working"), ("some", "text", "Broken") )
   ? IF( (.T.,1,.F.), ("some", "text", "Broken"), ("some", "text", "IF Working") )

   ? IF( (.T. .OR. .F.), IF( .T., "Working", "Broken" ), IF( .F., "Broken", "Working" ) )

   /* The following code should generate syntax error if uncommented
    * because IF token followed by any three expressions is interpreted
    * as IIF inline
    */
// IF( .T., .F., .T. )
//    ? "Working"
// ELSE
//    ? "Broken"
// ENDIF

   RETURN

STATIC FUNCTION Something( x, y, z )

   // This does something and it does it well/

   Return( NIL )

// pos (was neg 63s; SOURCE UNCHANGED, role converted with oracle
// capture): a logical store into a Dyn slot lands tag 3 - the parexpr
// piece admits it (the original assigns booleans into NIL-holding
// locals). Readback pinned separately in t1382.
procedure main()
   p( .t. )
   return
function p( x )
   ? x
   x := .f.
   return

function main()
? ("discard",1)
return

function main()
? (1,"last")
return

// pos (was neg t1040; SOURCE UNCHANGED, role converted with oracle
// capture): a Dyn VARIABLE as a discarded sequence element reads the
// slot borrowed - no payload ownership moves. Admitted with the
// parexpr piece alongside NIL-only calls. Observable variant: t1381.
function main()
local d := NIL
(d, 1)
return

// pos: inline IIF over comma sequences, including rodata string
// sequences (parexpr's ("some", "text", ...) shapes).
function main()
    ? IF( (.F.,0,.T.), ("some", "text", "IF Working"), ("some", "text", "Broken") )
    ? IF( (.T.,1,.F.), ("some", "text", "Broken"), ("some", "text", "IF Working") )
    ? IF( (.T. .OR. .F.), IF( .T., "Working", "Broken" ), IF( .F., "Broken", "Working" ) )
    return nil

// pos: `Return( NIL )` is the same value-free NIL return as bare
// `return nil` (parexpr.prg's own form), in main and in a function.
function something()
    Return( NIL )
function main()
    ? something()
    Return( NIL )

// pos: `#pragma -es<N>` (warning severity) is inert here - warnings do
// not exist in this dialect, so the switch changes no byte of output.
#pragma -es0
function main()
    ? ( 1, 2, 3 )
    return nil

// pos: NIL-only detection only trusts return EXPRESSIONS. A conditional
// bare return plus the closing `return nil` stays NIL-only (discarded
// in a sequence); a recursive NIL-only function is NIL-only too (the
// recursive call is a statement, never a returned value). A function
// returning any expression is NOT NIL-only (named limit, t1378).
function cond_ret(x)
    if x > 0
        return
    endif
    return nil
function rec_nil(n)
    if n > 1
        rec_nil(n - 1)
    endif
    return nil
function main()
    ? ( cond_ret(1), "ok" )
    ? ( cond_ret(0), "ok" )
    ? ( rec_nil(3), "ok" )
    return nil

// pos: observable variant of the t1040 admission - the discarded Dyn
// variable is read borrowed, the sequence value is the last element.
function main()
local d := NIL
? (d, 2)
return

// pos: observable variant of the t711 admission - a logical stored
// into a Dyn slot (tag 3) reads back as a logical.
procedure main()
   p( .t. )
   return
function p( x )
   ? x
   x := .f.
   ? x
   return
